from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate batch_size is integer 1..100, reject bool first
    if isinstance(batch_size, bool):
        raise ValueError("batch_size must be an integer, not bool")
    if not isinstance(batch_size, int) or batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

import api
from queueing import payload as make_payload
from worker import execute

def test_submit_default_batch_size():
    # Default batch_size=20
    result = api.submit("owner1", lambda x: x)
    assert isinstance(result, dict)
    assert result["owner"] == "owner1"
    assert result["batch_size"] == 20

def test_submit_custom_batch_size():
    # Custom valid batch_size values
    for val in [1, 50, 100]:
        result = api.submit("owner1", lambda x: x, batch_size=val)
        assert result["batch_size"] == val, f"Failed for batch_size={val}"

def test_submit_invalid_batch_size_zero():
