def test_worker_execute_with_batch_size():
    # Worker should use batch_size from payload
    task = make_payload("test_owner", batch_size=50)
    def mock_process(owner, bs):
        return (owner, bs)
    result = execute(task, mock_process)
    assert result == ("test_owner", 50)

def test_worker_execute_legacy_no_batch_size():
    # Worker should use default batch_size=20 for legacy payloads
    task = make_payload("legacy_owner")
    def mock_process(owner, bs):
        return (owner, bs)
    result = execute(task, mock_process)
    assert result == ("legacy_owner", 20)

def test_payload_structure():
    p = make_payload("my_owner", batch_size=30)
